360	//    a time over all CTAs; the scratch holds X/A/AX/AAX/orth for the LARGEST 2D weight
361	//    + the per-CTA Frobenius-norm partials + inv_norm. The momentum buffer (muon_buf)
362	//    is NOT here — it PERSISTS across steps as optimizer state, bound to the m slice
363	//    (st.exp_avg). Largest decoder 2D weight: ff.0/ff.2 = 512×128 = 65536 numel; largest
364	//    rows = 512 ⇒ A = 512×512 (dectc::kDecMuonMaxNumel/kDecMuonMaxRows). Carved
365	//    UNCONDITIONALLY (≈ 4·65536 + 512² + nCTA + 1 floats ≈ 2 MB) so the opt-agnostic
366	//    launcher (dec_tc_launcher_scratch) fits every OptId; unused by every non-Muon cell
367	//    (its P2.7/P3-2D branches are if-constexpr'd out → byte-identical). ──
368	__host__ __device__ __forceinline__ int64_t dec_tc_muon_floats(int nCTA) {
369	    // X + AX + AAX + orth (each maxNumel) + A (maxRows²) + nrm_partials(nCTA) + inv_norm(1)
370	    return (int64_t)4 * dectc::kDecMuonMaxNumel
371	         + (int64_t)dectc::kDecMuonMaxRows * dectc::kDecMuonMaxRows
372	         + nCTA + 1;
373	}
374	// ── LookSAM (STAGED in-kernel SAM 2nd backward) transient scratch. The SAM step
375	//    perturbs p in place, runs a SECOND fwd+bwd at p', and needs (a) a param BACKUP
376	//    for the exact restore (eager clones p before perturbing) + (b) a SEPARATE g_sam
377	//    grad buffer so the 2nd backward does NOT clobber the first grad `grad` (sam_dir
378	//    = g_sam − grad reads both). Both are total-sized + transient (NOT persistent
379	//    state — sam_dir itself persists in the `extra` state slice, bound by the cell).
380	//    Carved UNCONDITIONALLY (≈ 2·422755 ≈ 3.4 MB) so the opt-agnostic launcher fits
381	//    every OptId; unused by every non-LookSAM cell (its phase is if-constexpr'd out
382	//    → byte-identical). nrm_partials(nCTA)+inv_norm(1) for the ‖g‖ reduction reuse
383	//    the loss workspace (sq_part/coef_bc, as GrokAdamW's P2.5 does), so no extra here. ──
384	__host__ __device__ __forceinline__ int64_t dec_tc_looksam_floats() {
385	    return (int64_t)2 * kDecTotalElems;       // [sam_backup | sam_grad]
386	}
387	__host__ __device__ __forceinline__ int64_t dec_tc_workspace_floats(int T, int B, int nCTA) {
388	    return dec_tc_acts_floats(T, B)
389	         + (int64_t)nCTA * dectc::dec_tile_scratch_total_f32()
390	         + (int64_t)nCTA * dectc::kLnVecElems
391	         + nCTA + 1
392	         + dec_tc_dw_part_floats()            // split-K dW partials (G>1)
393	         + dec_tc_opt_reduce_floats(nCTA)     // STAGED-opt (Prodigy) reduce slots
394	         + dec_tc_muon_floats(nCTA)           // STAGED-opt (Muon) NS per-matrix scratch
395	         + dec_tc_looksam_floats();           // STAGED-opt (LookSAM) SAM 2nd-bwd scratch
396	}
