398	template <OptId Opt>
399	__global__ void __launch_bounds__(SG_TC_MEGA_BLOCK)
400	fused_decoder_megakernel_tc(PersistentContext ctx,
401	                            float* __restrict__ params,
402	                            DecoderTokenCtx tok,
403	                            float* __restrict__ grad,
404	                            float lr, int step, FusedOptState st) {
405	    __shared__ DecTcSmem sm;
406	    GridBarrier bar = ctx.barrier();
407	    const int cta = blockIdx.x;
408	    const int nCTA = (int)ctx.n_ctas;
409	    const int B = tok.B;
410	    const int T = B * dec::kSeq;
411	
412	    // Workspace partition.
413	    float* ws = tok.workspace;
414	    const int64_t acts_f = dec_tc_acts_floats(T, B);
415	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
416	    float* scratch_base = ws + acts_f;
417	    const int64_t scratch_per = dectc::dec_tile_scratch_total_f32();
418	    float* lnvec_base = scratch_base + (int64_t)nCTA * scratch_per;
419	    float* loss_part  = lnvec_base + (int64_t)nCTA * dectc::kLnVecElems;
420	    float* loss_out   = loss_part + nCTA;
421	    // Split-K dW partials (G>1): the (gt,kc) 64×N partial tiles, carved AFTER the
422	    // loss slot (matches dec_tc_workspace_floats's term order). G==1 → dw_part unused.
423	    float* dw_part    = loss_out + 1;
424	    const int kDwG    = dectc::kDecDwSplitK;
425	    // STAGED-opt cross-CTA reduce slots (Prodigy d), carved AFTER the dW partials
426	    // (matches dec_tc_workspace_floats's term order). Unused unless Opt==Prodigy.
427	    float* opt_reduce = dw_part + dec_tc_dw_part_floats();
428	    // Muon NS per-matrix scratch, carved AFTER the Prodigy reduce slots (matches
429	    // dec_tc_workspace_floats's term order — carving it LAST keeps every prior
430	    // region's offset unchanged, so the 5 already-green cells are byte-identical).
431	    // Unused unless Opt==Muon. Layout (mirrors the vit twin):
432	    //   [muon_X | muon_AX | muon_AAX | muon_orth] (each kDecMuonMaxNumel)
433	    //   [muon_A (kDecMuonMaxRows²)] [nrm_partials (nCTA)] [inv_norm (1)]
434	    float* muon_base = opt_reduce + dec_tc_opt_reduce_floats(nCTA);
435	    // LookSAM SAM 2nd-backward scratch, carved AFTER the Muon scratch (term order
436	    // matches dec_tc_workspace_floats — carving it LAST keeps every prior region's
437	    // offset unchanged, so the already-green cells are byte-identical). Layout:
438	    //   [sam_backup (total)] [sam_grad (total)]. Unused unless Opt==LookSAM.
439	    float* sam_backup = muon_base + dec_tc_muon_floats(nCTA);
440	    float* sam_grad   = sam_backup + kDecTotalElems;
441	
442	    dectc::DecActs acts = dectc::dec_acts_bind(acts_base, T, B);
443	    dectc::DecTileScratch sc = dectc::dec_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
444	    float* my_lnvec = lnvec_base + (int64_t)cta * dectc::kLnVecElems;
445	
446	    DecWeights w = dec_bind(params);
447	
448	    // ── P0: zero this CTA's LN-vec partials + loss slot (dW/embed grads are
449	    //    written-once → no pre-zero). ──
450	    for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
451	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
452	    bar.sync();   // B0
453	
454	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
455	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
456	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
457	    const int nrows_tile = dectc::kTileM;
458	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
459	    float nll_acc = 0.0f;
460	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
461	        const int g0 = ti * nrows_tile;
462	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
463	        float nll = dectc::dectc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
464	                                              sm.sA, sm.sB, sm.red);
465	        dectc::dectc_backward_tile(w, g0, nrows, B, acts, sc, tok.targets,
466	                                   my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
467	        if (threadIdx.x == 0) nll_acc += nll;
468	        __syncthreads();
469	    }
470	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
471	    bar.sync();   // B1: all acts (X + dY) + LN-vec partials complete
472	
473	    // ── P2: assemble all 30 grads into `grad`. dW output-stationary (gt %
474	    //    nCTA), biases, embedding owner-scan, LN-vec reduce. No partials. The 9
475	    //    dW specs are built into SHARED smem (thread 0; identical for all) so the
476	    //    9-spec array is NOT on every thread's stack (shrinks the launch's local
477	    //    reservation — the persistent kernel must place on a memory-tight GPU). ──
478	    if (threadIdx.x == 0) dectc::dectc_build_dw_specs(acts, B, T, sm.spec);
479	    __syncthreads();
480	    dectc::DecDwSpec* spec = sm.spec;
481	    const int n_dw = dectc::dectc_dw_total_tiles<SG_TUNED_TILE_N>(spec);
482	    if (kDwG > 1) {
483	        // SPLIT-K (multi-CTA tiling): fan (n_dw·G) (tile,chunk) partials over the
484	        // grid so the ~62% idle SMs do work; deterministic ascending-chunk reduce.
485	        for (int item = cta; item < n_dw * kDwG; item += nCTA) {
486	            const int gt = item / kDwG, kc = item % kDwG;
487	            dectc::dectc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
488	        }
489	        bar.sync();   // all (gt,kc) partials complete before the reduce reads them
490	        dectc::dectc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec, n_dw, kDwG, dw_part, grad, cta, nCTA);
491	    } else {
492	        for (int gt = cta; gt < n_dw; gt += nCTA)
493	            dectc::dectc_dw_run_tile<SG_TUNED_TILE_N>(spec, gt, grad, sm.sA, sm.sB);
494	    }
495	    dectc::dectc_dw_biases(spec, grad);
496	    dectc::dectc_embed_owner_scan(acts, tok.tokens, T, grad, cta, nCTA);
497	    dectc::dectc_lnvec_reduce(lnvec_base, grad, nCTA, cta);
498	    // Loss reduce (fp64) by CTA 0.
499	    if (cta == 0 && threadIdx.x == 0) {
500	        double s = 0.0;
501	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
502	        *tok.loss_out = (float)(s / (double)B);
503	    }
504	    (void)loss_out;
505	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue
506	
507	    // ── P2.4 (LookSAM ONLY, SAM steps): the MODEL-COUPLED SAM 2nd backward that
508	    //    produces st.sam_dir = g_sam − g (INTEGRATION-OPTSTAGES §6). Eager LookSAM,
509	    //    every k steps (looksam.py sam_step + looksam.h:27-59):
510	    //      ‖g‖     = GLOBAL L2 norm over ALL reduced grads (compute_sam_grad_norm_
511	    //                device_side); rho_over_norm = rho/‖g‖
512	    //      p'      = p + rho_over_norm·g          (perturb in the grad direction;
513	    //                backup = p.clone() for the exact restore — fp32 add is not
514	    //                bit-reversible, so we MUST save, not subtract back)
515	    //      g_sam   = ∇L(p')                       (a FULL SECOND in-kernel fwd+bwd
516	    //                + deterministic grad assembly at the perturbed weights, written
517	    //                to the SEPARATE `sam_grad` buffer so `grad` (the first grad the
518	    //                apply tail blends from) is untouched)
519	    //      sam_dir = g_sam − g                    (cached in the PERSISTENT `extra`
520	    //                state slice == st.sam_dir; reused verbatim on the k−1 intervening
521	    //                steps where looksam_sam==0, so NO 2nd pass runs then)
522	    //      restore p = backup
523	    //    The apply tail (P3, apply_optimizer<LookSAM>) then blends g_adj=(1−α)g+α·
524	    //    sam_dir and runs AdamW — UNCHANGED. DETERMINISM: the ‖g‖ reduction is the
525	    //    IDENTICAL deterministic ascending-CTA shape as GrokAdamW's P2.5 (fixed
526	    //    contiguous per-CTA range → per-CTA partial → CTA0 ascending sum), and the
527	    //    2nd fwd+bwd+assembly reuses the SAME A/A/A-clean machinery as the first pass
528	    //    (fixed tile ownership, ascending-k reductions), so the whole phase is
529	    //    deterministic BY CONSTRUCTION. Guarded so every other opt's path is
530	    //    byte-identical (no extra barrier / work). On a NON-SAM step (looksam_sam==0)
531	    //    this whole block is skipped — st.sam_dir already holds the cached direction.
532	    if constexpr (Opt == OptId::LookSAM) {
533	        if (st.looksam_sam != 0.0f) {
534	            // (a) GLOBAL ‖g‖ over the reduced grad, deterministic (reuse the loss
535	            //     workspace as P2.5 does: loss_part[nCTA] = per-CTA Σg², loss_out[1]
536	            //     broadcasts rho_over_norm). The reduced loss is already in
537	            //     *tok.loss_out (host state), so this is free scratch.
538	            float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
539	            float* ron_bc  = loss_out;           // [1] broadcast rho_over_norm
540	            const int64_t total = kDecTotalElems;
541	            {
542	                const int64_t base = total / nCTA, rem = total % nCTA;
543	                const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
544	                const int64_t ecnt = base + (cta < rem ? 1 : 0);
545	                float tsum = 0.0f;
546	                for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
547	                    const float gv = grad[e0 + i];
548	                    tsum += gv * gv;
549	                }
550	                float* red = sm.red;
551	                red[threadIdx.x] = tsum;
552	                __syncthreads();
553	                for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
554	                    if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
555	                    __syncthreads();
556	                }
557	                if (threadIdx.x == 0) sq_part[cta] = red[0];
558	                bar.sync();   // B2.4a: all per-CTA Σg² partials complete
559	                if (cta == 0 && threadIdx.x == 0) {
560	                    double ss = 0.0;
561	                    for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
562	                    const float gnorm = sqrtf((float)ss);
563	                    // rho / ‖g‖ (matches bindings.cpp looksam_perturb_all). gnorm>0 in
564	                    // any real training step; guard div-by-0 → 0 (no perturb) to be safe.
565	                    *ron_bc = (gnorm > 0.0f) ? (st.rho / gnorm) : 0.0f;
566	                }
567	                bar.sync();   // B2.4b: rho_over_norm broadcast ready
568	            }
569	            const float rho_over_norm = *ron_bc;
570	            // (b) Backup + perturb p in place: p' = p + rho_over_norm·g. Grid-strided
571	            //     over the flat param vector (each element owned once → no race).
572	            {
573	                const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
574	                for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
575	                     i < total; i += gstride) {
576	                    sam_backup[i] = params[i];
577	                    params[i] = params[i] + rho_over_norm * grad[i];
578	                }
579	            }
580	            bar.sync();   // B2.4c: all params perturbed before the 2nd forward reads them
581	            // (c) SECOND fwd+bwd at the perturbed weights → g_sam in `sam_grad`. Mirror
582	            //     P1 + P2 EXACTLY, but: re-zero the lnvec partials (they accumulate),
583	            //     do NOT write the loss (keep the first-pass loss), and assemble into
584	            //     `sam_grad` (NOT `grad`). `w` wraps `params` (now perturbed) so the
585	            //     tile fns read the perturbed weights with no re-bind needed.
586	            for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
587	            bar.sync();   // B2.4d: lnvec partials cleared before the 2nd backward accumulates
588	            for (int ti = cta; ti < n_tiles; ti += nCTA) {
589	                const int g0 = ti * nrows_tile;
590	                const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
591	                dectc::dectc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
592	                                          sm.sA, sm.sB, sm.red);
593	                dectc::dectc_backward_tile(w, g0, nrows, B, acts, sc, tok.targets,
594	                                           my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
595	                __syncthreads();
596	            }
597	            bar.sync();   // B2.4e: all 2nd-pass acts (X + dY) + LN-vec partials complete
598	            // Re-build the dW specs from the 2nd-pass acts (dY adjoints changed).
599	            if (threadIdx.x == 0) dectc::dectc_build_dw_specs(acts, B, T, sm.spec);
600	            __syncthreads();
601	            dectc::DecDwSpec* spec2 = sm.spec;
602	            const int n_dw2 = dectc::dectc_dw_total_tiles<SG_TUNED_TILE_N>(spec2);
603	            if (kDwG > 1) {
604	                for (int item = cta; item < n_dw2 * kDwG; item += nCTA) {
605	                    const int gt = item / kDwG, kc = item % kDwG;
606	                    dectc::dectc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec2, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
607	                }
608	                bar.sync();
609	                dectc::dectc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec2, n_dw2, kDwG, dw_part, sam_grad, cta, nCTA);
610	            } else {
611	                for (int gt = cta; gt < n_dw2; gt += nCTA)
612	                    dectc::dectc_dw_run_tile<SG_TUNED_TILE_N>(spec2, gt, sam_grad, sm.sA, sm.sB);
613	            }
614	            dectc::dectc_dw_biases(spec2, sam_grad);
615	            dectc::dectc_embed_owner_scan(acts, tok.tokens, T, sam_grad, cta, nCTA);
616	            dectc::dectc_lnvec_reduce(lnvec_base, sam_grad, nCTA, cta);
617	            bar.sync();   // B2.4f: g_sam fully assembled in sam_grad
618	            // (d) sam_dir = g_sam − g (into the persistent extra slice) + restore p.
619	            {
620	                const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
621	                for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
622	                     i < total; i += gstride) {
623	                    // st.sam_dir is the extra-slice base (host-bound). g_sam − g.
624	                    const_cast<float*>(st.sam_dir)[i] = sam_grad[i] - grad[i];
625	                    params[i] = sam_backup[i];   // restore the ORIGINAL weights
626	                }
627	            }
628	            bar.sync_reset(ctx.g_next_task);   // B2.4g: params restored + sam_dir ready; reset queue for P3
629	        }
630	    }
