633	    //    grokadamw clips the WHOLE grad set to grad_clip via a GLOBAL L2 norm
634	    //    (clip_grad_norms_device_side → total_norm = sqrt(Σ_i ‖g_i‖²),
635	    //    clip_coef = grad_clip/(total_norm+1e-6) when total_norm>grad_clip,
636	    //    else 1) BEFORE the apply. We replicate it on the REDUCED grad with a
637	    //    deterministic ascending reduction (no float atomics): each CTA sums a
638	    //    contiguous element-range into a per-CTA partial slot, CTA0 sums the
639	    //    partials in ascending CTA order → total_norm → clip_coef, broadcast via
640	    //    a workspace slot. The grad buffer is NOT mutated (the return_grad oracle
641	    //    + the eager-side clip must both see the unclipped reduced grad); the
642	    //    coefficient is applied per-element inside apply_optimizer<GrokAdamW>.
643	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
644	    if constexpr (Opt == OptId::GrokAdamW) {
645	        // Reuse the (now-consumed) loss workspace: loss_part[nCTA] holds per-CTA
646	        // partial sum-of-squares; loss_out (1 float) broadcasts clip_coef. The
647	        // reduced loss is already in *tok.loss_out (state), so this is free scratch.
648	        float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
649	        float* coef_bc = loss_out;           // [1] broadcast clip_coef
650	        // Per-CTA contiguous element range over `grad` (the reduced grad, [total]).
651	        const int64_t total = kDecTotalElems;
652	        const int64_t base = total / nCTA, rem = total % nCTA;
653	        const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
654	        const int64_t ecnt = base + (cta < rem ? 1 : 0);
655	        // Thread-local partial → block reduce (fixed tree) → thread0 writes the slot.
656	        float tsum = 0.0f;
657	        for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
658	            const float gv = grad[e0 + i];
659	            tsum += gv * gv;

