106	// Compile-time guard: the byte budget the launcher uses (sizeof(VitSampleSmem))
107	// MUST equal the literal the layout header documents + bounds-checks (227 KB cap).
108	static_assert(sizeof(VitSampleSmem) == (size_t)vit_layout_check::kVitSampleSmemBytes,
109	              "fused_vit_megakernel: sizeof(VitSampleSmem) != the documented "
110	              "kVitSampleSmemBytes in vit_layout.cuh — update both together.");
