112	// Rebase a FusedOptState's per-element state pointers to a parameter-tensor slice
113	// at `off` within the flat [m|v|extra] layout. Per-TENSOR fields and all scalars
114	// pass through unchanged. (Identical to the decoder's rebase_state; redefined here
115	// under a vit_ name so this header stays self-contained — the decoder file is
116	// owned by a sibling agent and must not be included.)
117	template <OptId Opt>
118	__device__ __forceinline__ FusedOptState
119	vit_rebase_state(const FusedOptState& s, int64_t off) {
120	    FusedOptState t = s;  // scalars + per-tensor pointers copy as-is
121	    if (t.exp_avg)    t.exp_avg    += off;
122	    if (t.exp_avg_sq) t.exp_avg_sq += off;
123	    if (t.ema)        t.ema        += off;
124	    if (t.sam_dir)    t.sam_dir    += off;
125	    if (t.s_track)    t.s_track    += off;
126	    if (t.mu)         t.mu         += off;
127	    if (t.orth)       t.orth       += off;
128	    if (t.smart_grad) t.smart_grad += off;
129	    if (t.param_init) t.param_init += off;   // Prodigy trajectory anchor p0
130	    return t;
131	}
