133	// The L3-REAL ViT megakernel needs the FLOAT patch path + a grad-partial
134	// workspace. Kept a SEPARATE kernel + launcher (not folded into the surrogate
135	// fused_megakernel) so the surrogate path is untouched.
136	//
137	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
138	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
139	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
140	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
141	// total == kVitTotalElems == 418017.
142	struct ViTInputCtx {
143	    const float* patches;  // [B, kNPatch, kPatch] fp32 image patches
144	    const int*   targets;  // [B]                  int32 target ids in [0,kVocab)
145	    int          B;        // batch size
146	    float*       workspace; // grad partials + loss partials + reduced loss
147	    float*       loss_out;  // device float the kernel writes the mean loss into
148	};
149	
150	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
151	//    threads/CTA. VitSampleSmem (~183.67 KB) lives in DYNAMIC smem (extern). ────
152	// sizes/offsets are NOT host-passed: per-tensor numel/offset live in the
153	// __constant__ tables kVitSizes/kVitOffsets (vit_layout.cuh), read directly by
154	// the reduce + optimizer phases.
155	template <OptId Opt>
156	__global__ void __launch_bounds__(SG_TUNED_MEGA_BLOCK)
157	fused_vit_megakernel(PersistentContext ctx,
158	                     float* __restrict__ params,
159	                     ViTInputCtx in,
160	                     float* __restrict__ grad,        // reduced grad [total]
161	                     float lr, int step, FusedOptState st) {
162	    extern __shared__ char vit_smem_raw[];
163	    VitSampleSmem& sm = *reinterpret_cast<VitSampleSmem*>(vit_smem_raw);
164	    GridBarrier bar = ctx.barrier();
165	    const int cta = blockIdx.x;
166	    const int nCTA = (int)ctx.n_ctas;
167	    const int64_t total = kVitTotalElems;
168	    float* my_partial = in.workspace + (int64_t)cta * total;   // this CTA's dW
169	    float* loss_part = in.workspace + (int64_t)nCTA * total;   // [nCTA]
170	
171	    // §3.4 register repartition (producer WG gives back, consumer WG claims).
172	    const int wg = threadIdx.x / 128;
173	    if (wg == 0) ::sg::sm90::wgs::warpgroup_reg_dealloc<32>();
174	    else         ::sg::sm90::wgs::warpgroup_reg_alloc<200>();
175	
176	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
177	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
178	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
179	    bar.sync();   // B0
180	
181	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
182	    VitWeights w = vit_bind(params);
183	    VitGrad g = vit_bind_grad(my_partial);
184	    const int B = in.B;
185	    const int base = B / nCTA, rem = B % nCTA;
186	    const int b0 = cta * base + (cta < rem ? cta : rem);
187	    const int cnt = base + (cta < rem ? 1 : 0);
188	    const int b1 = b0 + cnt;
189	    __shared__ int tgt_s;
190	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
191	    const int patch_elems = vit::kNPatch * vit::kPatch;   // 16*49 = 784
192	    for (int b = b0; b < b1; ++b) {
193	        // Load this sample's float patches into smem (cooperative).
194	        const float* src = in.patches + (int64_t)b * patch_elems;
195	        for (int i = threadIdx.x; i < patch_elems; i += blockDim.x)
196	            sm.patch[i / vit::kPatch][i % vit::kPatch] = src[i];
197	        if (threadIdx.x == 0) tgt_s = in.targets[b];
198	        __syncthreads();
199	        float nll = vit_forward_sample(w, tgt_s, &sm);
200	        vit_backward_sample(w, g, tgt_s, B, &sm);
201	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
202	        __syncthreads();   // sample boundary: all grad writes done before reuse
203	    }
204	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
205	    bar.sync();   // B1: all CTA partials + loss slots complete
206	
207	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
208	    //    (one task = one parameter tensor; sum its elements across CTAs in
209	    //    ascending CTA index). Summation ORDER (ascending cta) is fixed →
210	    //    deterministic regardless of which CTA grabs the task. ─────────────────
211	    {
212	        __shared__ int task_slot;
213	        TaskQueue q = ctx.queue();
214	        for (int t = q.next_block(&task_slot); t < kVitNumTensors;
215	             t = q.next_block(&task_slot)) {
216	            const int n = kVitSizes[t];
217	            const int64_t off = (int64_t)kVitOffsets[t];
218	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
219	                float acc = 0.0f;
220	                for (int c = 0; c < nCTA; ++c)
221	                    acc += in.workspace[(int64_t)c * total + off + i];
222	                grad[off + i] = acc;
223	            }
224	        }
225	    }
226	    // Loss reduction (fp64 ordered) by CTA 0 only — the loss rel-tol is the
227	    // tightest gate; fp32 atomic-summing many terms can miss it.
228	    if (cta == 0 && threadIdx.x == 0) {
229	        double s = 0.0;
230	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
231	        float mean = (float)(s / (double)B);
232	        *in.loss_out = mean;
233	    }
234	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
235	
236	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 32
237	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
238	    st.lr = lr;
239	    {
240	        __shared__ int task_slot;
241	        TaskQueue q = ctx.queue();
242	        for (int t = q.next_block(&task_slot); t < kVitNumTensors;
243	             t = q.next_block(&task_slot)) {
244	            const int n = kVitSizes[t];
245	            const int64_t off = (int64_t)kVitOffsets[t];
246	            const FusedOptState ts = vit_rebase_state<Opt>(st, off);
247	            float* __restrict__ p = params + off;
248	            const float* __restrict__ gg = grad + off;
249	            for (int i = threadIdx.x; i < n; i += blockDim.x)
250	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
251	        }
252	    }
253	}
