255	// ── Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
256	//    Mirrors launch_fused_decoder_megakernel's hang-freedom contract (occupancy≥1
257	//    or refuse), PLUS the DYNAMIC-SMEM opt-in that the ViT footprint requires:
258	//      (1) cudaFuncSetAttribute(MaxDynamicSharedMemorySize, sizeof(VitSampleSmem))
259	//      (2) dynamicSMemBytes = sizeof(VitSampleSmem) in the occ≥1 query
260	//      (3) dynamicSMemBytes = sizeof(VitSampleSmem) at <<<...>>>
261	//    All three are mandatory; missing any one makes the launch silently fail. ───
262	template <OptId Opt>
263	cudaError_t launch_fused_vit_megakernel(
264	        PersistentContext ctx, float* params, ViTInputCtx in,
265	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream) {
266	    int dev = 0;
267	    cudaError_t err = cudaGetDevice(&dev);
268	    if (err != cudaSuccess) return err;
269	    int n_sms = 0;
270	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
271	    if (err != cudaSuccess) return err;
272	
273	    const int dyn_smem = (int)sizeof(VitSampleSmem);   // ≈ 188080 B (183.67 KB)
274	
275	    // (1) Opt in to >48 KB dynamic smem for THIS kernel. Without this the launch
276	    //     fails with cudaErrorInvalidValue (the static 48 KB default applies).
277	    err = cudaFuncSetAttribute(
278	        (const void*)&fused_vit_megakernel<Opt>,
279	        cudaFuncAttributeMaxDynamicSharedMemorySize, dyn_smem);
280	    if (err != cudaSuccess) return err;
281	
282	    // (2) Occupancy with the REAL dynamic-smem request (hang-freedom is honest).
283	    int occ = 0;
284	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
285	        &occ, (const void*)&fused_vit_megakernel<Opt>, SG_TUNED_MEGA_BLOCK,
286	        /*dynamicSMemBytes=*/dyn_smem);
287	    if (err != cudaSuccess) return err;
288	    // At least one CTA per SM must be resident or the grid barrier can never be
289	    // satisfied. ~183.67 KB dynamic smem fits the sm_90 227 KB cap at occ=1 (the
290	    // persistent megakernel is one-CTA-per-SM by design); if it cannot place one
291	    // block/SM, REFUSE rather than hang.
292	    assert(occ >= 1 &&
293	           "fused_vit_megakernel: 0 blocks/SM — GridBarrier would hang. The ViT "
294	           "per-sample smem (~184KB dynamic) + regs exceed one-block-per-SM "
295	           "occupancy on this device; reduce footprint or fall back to eager.");
296	    if (occ < 1) return cudaErrorLaunchOutOfResources;
297	
298	    const unsigned launch_ctas = (unsigned)n_sms;
299	    ctx.n_ctas = launch_ctas;
300	
301	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
302	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
303	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
304	
305	    // (3) Launch WITH the dynamic-smem byte count.
306	    dim3 grid(launch_ctas), block(SG_TUNED_MEGA_BLOCK);
307	    fused_vit_megakernel<Opt><<<grid, block, dyn_smem, stream>>>(
308	        ctx, params, in, grad, lr, step, st);
309	    return cudaGetLastError();
310	}
