312	// ════════════════════════════════════════════════════════════════════════════
313	//  WGMMA CELL DRIVER (DESIGN-TC-PIPELINE.md Fork B, the ViT twin of the decoder
314	//  R2.3 driver). Compiled only under the wgmma token; the scalar path above is
315	//  untouched. The TC path's per-CTA tile scratch lives in HBM (NOT dynamic smem)
316	//  — the only smem the TC kernel needs is the tiny wgmma staging arena (one
317	//  A(64×16) + one B(N×16) bf16 tile + a 256-float reduction + the 10 dW specs),
318	//  which is STATIC (≈ 7 KB), so this kernel — unlike the scalar ViT one — needs
319	//  NO dynamic-smem opt-in. The big ViT activation footprint (which forced the
320	//  scalar path to 184 KB dynamic smem) becomes HBM acts here (Fork B), so the
321	//  occupancy story is the decoder TC one: static smem, 0 dynamic.
322	// ════════════════════════════════════════════════════════════════════════════
323	#if (SG_TUNED_GEMM_IMPL == SG_GEMM_IMPL_WGMMA)
324	
325	// TC megakernel threads: 256 (the engine's producer+consumer warpgroup layout;
326	// wgmma is warpgroup-scoped on threads 0..127). We do NOT apply the scalar
327	// path's asymmetric setmaxnreg (it would STARVE the MMA warpgroup); the
328	// validated selftest ran no split. We match it.
329	#define SG_VIT_TC_MEGA_BLOCK 256
330	
331	// ── smem arena for the unpipelined engine: one A(64×16) + one B(N×16) bf16 tile
332	//    + the 256-float reduction slot + the 10 dW specs (identical for all threads
333	//    → shared, not per-thread stack). 16B-aligned. N = SG_TUNED_TILE_N. ──
334	struct VitTcSmem {
335	    __nv_bfloat16 sA[64 * 16];
336	    __nv_bfloat16 sB[SG_TUNED_TILE_N * 16];
337	    float red[256];
338	    vittc::VitDwSpec spec[10];
339	};
340	
341	// ── TC workspace layout (carved from in.workspace; the host sizes it). Regions
342	//    (float units):
343	//      [0 .. acts_f)                      : VitActs bf16 region (reinterpreted)
344	//      [acts_f .. acts_f + nCTA*scratch)  : per-CTA tile scratch (f32)
345	//      [.. + nCTA*kLnVecElems)            : per-CTA LN-vec partials (f32)
346	//      [.. + nCTA)                        : per-CTA loss slots (f32)
347	//      [.. + 1)                           : reduced scalar loss (host reads it)
348	//    acts_f = ceil(acts_bf16 / 2). ──
349	__host__ __device__ __forceinline__ int64_t vit_tc_acts_floats(int T, int B) {
350	    return (vittc::vit_acts_bf16_count(T, B) + 1) / 2;
351	}
352	// dW split-K partial floats (0 when G==1 → no extra scratch, the single-CTA path).
353	__host__ __device__ __forceinline__ int64_t vit_tc_dw_part_floats() {
354	    return vittc::vit_dw_part_floats(vittc::kVitDwSplitK);
355	}
356	// STAGED-optimizer cross-CTA reduction scratch (Prodigy d-estimate). The Prodigy
357	// stage publishes per-CTA (r,s) slots (2*nCTA) + a reduced-d slot (1) — an owner-
358	// computes tree (opt_stages_precompute.cuh), NO float atomic. Sized for the LARGEST
359	// nCTA (one CTA/SM = #SMs); tiny (≤ 2*132+1 floats) and carved UNCONDITIONALLY so
360	// the opt-agnostic launcher allocates one workspace fitting every OptId. Unused by
361	// AdamW/Lion/… (their P3 never touches it) → those cells stay byte-identical.
362	__host__ __device__ __forceinline__ int64_t vit_tc_opt_reduce_floats(int nCTA) {
363	    return (int64_t)2 * nCTA + 1;            // [r slots | s slots | reduced d]
364	}
365	// ── Muon (STAGED grid-cooperative Newton-Schulz) per-matrix scratch. The NS chain
366	//    runs ONE 2D weight at a time over all CTAs; the scratch holds X/A/AX/AAX/orth
367	//    for the LARGEST 2D weight + the per-CTA Frobenius-norm partials + inv_norm. The
368	//    momentum buffer (muon_buf) is NOT here — it PERSISTS across steps as optimizer
369	//    state, bound to the m slice (st.exp_avg). Largest vit 2D weight: ff0/ff2 = 512×
370	//    128 = 65536 numel; largest rows = 512 ⇒ A = 512×512. Carved UNCONDITIONALLY
371	//    (≈ 4·65536 + 512² + nCTA + 1 floats ≈ 2 MB) so the opt-agnostic launcher fits
372	//    every OptId; unused by every non-Muon cell (byte-identical). ──
373	//    kVitMuonMaxNumel = max over 2D weights of rows*cols; kVitMuonMaxRows = max rows.
374	static constexpr int kVitMuonMaxNumel = vit::kDff * vit::kD;     // 512*128 = 65536 (ff0/ff2)
375	static constexpr int kVitMuonMaxRows  = vit::kDff;               // 512 (ff0 rows)
376	__host__ __device__ __forceinline__ int64_t vit_tc_muon_floats(int nCTA) {
377	    // X + AX + AAX + orth (each maxNumel) + A (maxRows²) + nrm_partials(nCTA) + inv_norm(1)
378	    return (int64_t)4 * kVitMuonMaxNumel
379	         + (int64_t)kVitMuonMaxRows * kVitMuonMaxRows
380	         + nCTA + 1;
381	}
382	__host__ __device__ __forceinline__ int64_t vit_tc_workspace_floats(int T, int B, int nCTA) {
383	    return vit_tc_acts_floats(T, B)
384	         + (int64_t)nCTA * vittc::vit_tile_scratch_total_f32()
385	         + (int64_t)nCTA * vittc::kLnVecElems
386	         + nCTA + 1
387	         + vit_tc_dw_part_floats()           // split-K dW partials (G>1)
388	         + vit_tc_opt_reduce_floats(nCTA)    // STAGED-opt (Prodigy) reduce slots
389	         + vit_tc_muon_floats(nCTA);         // STAGED-opt (Muon) NS per-matrix scratch
390	}
391	
392	#ifdef SG_VIT_PROFILE
393	// Diagnostic-only (behind SG_VIT_PROFILE; NEVER on the shipped path): per-phase
394	// clock64() deltas, max across CTAs (= critical-path duration per phase). Slots:
395	// [0]=P1 fwd, [1]=P1 bwd, [2]=B1 barrier wait, [3]=P2 dW-GEMM loop,
396	// [4]=P2 grad-assembly (biases+clspos+lnvec+loss), [5]=P3 opt tail. Read
397	// host-side via cudaMemcpyFromSymbol. clock64() is per-SM; a CTA stays on one SM
398	// so its own deltas are valid; atomicMax across CTAs gives the slowest CTA per
399	// phase.
400	__device__ unsigned long long g_vit_prof_max[6];
401	#endif
402	
403	template <OptId Opt>
404	__global__ void __launch_bounds__(SG_VIT_TC_MEGA_BLOCK)
405	fused_vit_megakernel_tc(PersistentContext ctx,
406	                        float* __restrict__ params,
407	                        ViTInputCtx in,
408	                        float* __restrict__ grad,
409	                        float lr, int step, FusedOptState st) {
410	    __shared__ VitTcSmem sm;
411	    GridBarrier bar = ctx.barrier();
412	    const int cta = blockIdx.x;
413	    const int nCTA = (int)ctx.n_ctas;
414	    const int B = in.B;
415	    const int T = B * vit::kSeq;
416	    const int Tp = B * vit::kNPatch;
417	
418	    // Workspace partition.
419	    float* ws = in.workspace;
420	    const int64_t acts_f = vit_tc_acts_floats(T, B);
421	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
422	    float* scratch_base = ws + acts_f;
423	    const int64_t scratch_per = vittc::vit_tile_scratch_total_f32();
424	    float* lnvec_base = scratch_base + (int64_t)nCTA * scratch_per;
425	    float* loss_part  = lnvec_base + (int64_t)nCTA * vittc::kLnVecElems;
426	    float* loss_out   = loss_part + nCTA;
427	    // Split-K dW partials (G>1): the (gt,kc) 64×N partial tiles, carved AFTER the
428	    // loss slot (matches vit_tc_workspace_floats's term order). G==1 → dw_part unused.
429	    float* dw_part    = loss_out + 1;
430	    const int kDwG    = vittc::kVitDwSplitK;
431	    // STAGED-opt cross-CTA reduce slots (Prodigy d), carved AFTER the dW partials
432	    // (matches vit_tc_workspace_floats's term order). Unused unless Opt==Prodigy.
433	    float* opt_reduce = dw_part + vit_tc_dw_part_floats();
434	    // Muon NS per-matrix scratch, carved AFTER the Prodigy reduce slots (matches
435	    // vit_tc_workspace_floats's term order). Unused unless Opt==Muon. Layout:
436	    //   [muon_X | muon_AX | muon_AAX | muon_orth] (each kVitMuonMaxNumel)
437	    //   [muon_A (kVitMuonMaxRows²)] [nrm_partials (nCTA)] [inv_norm (1)]
438	    float* muon_base = opt_reduce + vit_tc_opt_reduce_floats(nCTA);
439	
440	    vittc::VitActs acts = vittc::vit_acts_bind(acts_base, T, B);
441	    vittc::VitTileScratch sc = vittc::vit_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
442	    float* my_lnvec = lnvec_base + (int64_t)cta * vittc::kLnVecElems;
443	
444	    VitWeights w = vit_bind(params);
445	
446	    // ── P0: zero this CTA's LN-vec partials + loss slot (dW/cls/pos/patch grads
447	    //    are written-once → no pre-zero). ──
448	    for (int i = threadIdx.x; i < vittc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
449	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
450	    // STAGED-opt (Prodigy) reduce slots: INTEGRATION-OPTSTAGES.md §1 REQUIRES
451	    // prodigy_partials + prodigy_d zero-initialized before launch (the owner-computes
452	    // tree reads EVERY slot in ascending order; a CTA that claims no tensor in phaseA
453	    // still has its (r,s) slot read, and the persistent device workspace is NOT
454	    // re-zeroed between launches — so a stale slot from a prior step's reduction, or
455	    // garbage from the caching allocator, would make the cross-tensor d non-determi-
456	    // nistic / NaN). phaseA's block_reduce DOES write each slot, but zeroing here is
457	    // the contract guarantee + defends the prodigy_d broadcast slot. Guarded to the
458	    // Prodigy instantiation so every other cell is byte-identical (no extra work).
459	    if constexpr (Opt == OptId::Prodigy) {
460	        const int64_t n_opt = vit_tc_opt_reduce_floats(nCTA);   // 2*nCTA + 1
461	        for (int64_t i = (int64_t)cta * blockDim.x + threadIdx.x; i < n_opt;
462	             i += (int64_t)nCTA * blockDim.x)
463	            opt_reduce[i] = 0.0f;
464	    }
465	    bar.sync();   // B0
466	
467	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
468	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
469	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
470	    const int nrows_tile = vittc::kTileM;
471	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
472	    float nll_acc = 0.0f;
473	#ifdef SG_VIT_PROFILE
474	    unsigned long long prof_fwd = 0, prof_bwd = 0;
475	#endif
476	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
477	        const int g0 = ti * nrows_tile;
478	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
479	#ifdef SG_VIT_PROFILE
480	        __syncthreads(); unsigned long long _c0 = clock64();
481	#endif
482	        float nll = vittc::vittc_forward_tile(w, g0, nrows, acts, sc, in.patches, in.targets,
483	                                              sm.sA, sm.sB, sm.red);
484	#ifdef SG_VIT_PROFILE
485	        __syncthreads(); unsigned long long _c1 = clock64();
486	#endif
487	        vittc::vittc_backward_tile(w, g0, nrows, B, acts, sc, in.targets,
488	                                   my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
489	#ifdef SG_VIT_PROFILE
490	        __syncthreads(); unsigned long long _c2 = clock64();
491	        if (threadIdx.x == 0) { prof_fwd += _c1 - _c0; prof_bwd += _c2 - _c1; }
492	#endif
493	        if (threadIdx.x == 0) nll_acc += nll;
494	        __syncthreads();
495	    }
496	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
497	#ifdef SG_VIT_PROFILE
498	    if (threadIdx.x == 0) {
499	        atomicMax(&g_vit_prof_max[0], prof_fwd);
500	        atomicMax(&g_vit_prof_max[1], prof_bwd);
501	    }
502	    unsigned long long _b1a = (threadIdx.x == 0) ? clock64() : 0;
503	#endif
504	    bar.sync();   // B1: all acts (X + dY) + LN-vec partials complete
505	#ifdef SG_VIT_PROFILE
506	    if (threadIdx.x == 0) { unsigned long long _b1b = clock64(); atomicMax(&g_vit_prof_max[2], _b1b - _b1a); }
507	#endif
508	
509	    // ── P2: assemble all 32 grads into `grad`. dW output-stationary (gt % nCTA),
510	    //    biases, cls/pos owner-scan, LN-vec reduce. No partials. The 10 dW specs
511	    //    are built into SHARED smem (thread 0; identical for all). ──
512	    if (threadIdx.x == 0) vittc::vittc_build_dw_specs(acts, B, T, Tp, sm.spec);
513	    __syncthreads();
514	    vittc::VitDwSpec* spec = sm.spec;
515	    const int n_dw = vittc::vittc_dw_total_tiles<SG_TUNED_TILE_N>(spec);
516	#ifdef SG_VIT_PROFILE
517	    __syncthreads(); unsigned long long _dwa = (threadIdx.x == 0) ? clock64() : 0;
518	#endif
519	    if (kDwG > 1) {
520	        // SPLIT-K (multi-CTA tiling): fan (n_dw·G) (tile,chunk) partials over the
521	        // grid so the ~60% idle SMs do work; deterministic ascending-chunk reduce.
522	        for (int item = cta; item < n_dw * kDwG; item += nCTA) {
523	            const int gt = item / kDwG, kc = item % kDwG;
524	            vittc::vittc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec, gt, kc, kDwG, acts.dh0, dw_part, sm.sA, sm.sB);
525	        }
526	        bar.sync();   // all (gt,kc) partials complete before the reduce reads them
527	        vittc::vittc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec, n_dw, kDwG, dw_part, grad, cta, nCTA);
528	    } else {
529	        for (int gt = cta; gt < n_dw; gt += nCTA)
530	            vittc::vittc_dw_run_tile<SG_TUNED_TILE_N>(spec, gt, acts.dh0, grad, sm.sA, sm.sB);
531	    }
532	#ifdef SG_VIT_PROFILE
533	    __syncthreads();
534	    if (threadIdx.x == 0) { unsigned long long _dwb = clock64(); atomicMax(&g_vit_prof_max[3], _dwb - _dwa); }
535	    unsigned long long _gaa = (threadIdx.x == 0) ? clock64() : 0;
536	#endif
537	    vittc::vittc_dw_biases(spec, acts.dh0, grad, cta, nCTA);
538	    vittc::vittc_clspos_owner_scan(acts, T, grad, cta, nCTA);
539	    vittc::vittc_lnvec_reduce(lnvec_base, grad, nCTA, cta);
540	    // Loss reduce (fp64) by CTA 0.
541	    if (cta == 0 && threadIdx.x == 0) {
542	        double s = 0.0;
543	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
544	        *in.loss_out = (float)(s / (double)B);
545	    }
546	    (void)loss_out;
547	#ifdef SG_VIT_PROFILE
548	    if (threadIdx.x == 0) { unsigned long long _gab = clock64(); atomicMax(&g_vit_prof_max[4], _gab - _gaa); }
549	#endif
550	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue
551	
552	    // ── P2.5 (GrokAdamW ONLY): GLOBAL grad-norm clip coefficient. Identical to the
553	    //    decoder twin (fused_decoder_megakernel.cuh P2.5). Eager grokadamw clips the
554	    //    WHOLE grad set to grad_clip via a GLOBAL L2 norm (clip_grad_norms_device_side
555	    //    → total_norm = sqrt(Σ_i ‖g_i‖²), clip_coef = grad_clip/(total_norm+1e-6) when
556	    //    total_norm>grad_clip, else 1) BEFORE the apply. We replicate it on the REDUCED
557	    //    grad with a deterministic ascending reduction (no float atomics): each CTA sums
558	    //    a contiguous element-range into a per-CTA partial slot, CTA0 sums the partials
559	    //    in ascending CTA order → total_norm → clip_coef, broadcast via a workspace
560	    //    slot. The grad buffer is NOT mutated (the return_grad oracle + the eager-side
561	    //    clip must both see the unclipped reduced grad); the coefficient is applied
562	    //    per-element inside apply_optimizer<GrokAdamW>. Guarded so every other opt's P3
563	    //    is byte-identical (no extra barrier/work). Reuses loss_part/loss_out as free
564	    //    scratch (the reduced loss is already in *in.loss_out; the dW partials are
565	    //    consumed → that whole region after loss_out is also free).
566	    if constexpr (Opt == OptId::GrokAdamW) {
567	        float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
568	        float* coef_bc = loss_out;           // [1] broadcast clip_coef
569	        const int64_t total_e = kVitTotalElems;
570	        const int64_t base = total_e / nCTA, rem = total_e % nCTA;
571	        const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
572	        const int64_t ecnt = base + (cta < rem ? 1 : 0);
573	        float tsum = 0.0f;
574	        for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
575	            const float gv = grad[e0 + i];
576	            tsum += gv * gv;
577	        }
578	        // Block reduction via the smem the TC GEMM already owns (sm.red, fp32).
579	        float* red = sm.red;
580	        red[threadIdx.x] = tsum;
581	        __syncthreads();
582	        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
583	            if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
584	            __syncthreads();
585	        }
586	        if (threadIdx.x == 0) sq_part[cta] = red[0];
587	        bar.sync();   // B2.5a: all per-CTA sum-of-squares partials complete
588	        if (cta == 0 && threadIdx.x == 0) {
589	            double ss = 0.0;
590	            for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
591	            const float total_norm = sqrtf((float)ss);
592	            float coef = 1.0f;
593	            if (st.grad_clip > 0.0f && total_norm > st.grad_clip)
594	                coef = st.grad_clip / (total_norm + 1e-6f);
595	            *coef_bc = coef;
596	        }
597	        bar.sync();   // B2.5b: clip_coef broadcast slot ready for all CTAs
598	        st.clip_coef = *coef_bc;   // every CTA reads the single global coefficient
599	    }
600	
601	    // ── P2.6 (Prodigy ONLY): STAGED global-d estimate (cross-ALL-tensors reduce).
602	    //    Identical to the decoder twin's P2.6. The apply tail (apply_optimizer
603	    //    <Prodigy>) reads st.d_factor (the effective LR scale d), which is a single
604	    //    cross-tensor reduction (NOT per-element) → an IN-KERNEL phase here, BYTE-
605	    //    FAITHFUL to the live eager multi-tensor path (prodigy_sm90.cuh →
606	    //    launch_multi_tensor_prodigy_fused_reduce_step, the order prodigy.py executes):
607	    //      d_prev  = persisted d_lr  (step 1: d0 cold-start — the zero-init state slot
608	    //                is 0 but eager inits _d_lr=d0=1e-6, so seed it here)
609	    //      r_ema  <- beta3·r_ema + Σ d_prev²·<g, p0−p>     (decay persisted SCALAR,
610	    //      s_ema  <- beta3·s_ema + Σ d_prev²·|g|            then add this step's Σ)
611	    //      d       = max(d_prev, d_coef·r_ema/|s_ema|)      (prodigy_update_d; d_coef
612	    //                scales ONLY the candidate — persisted r_ema stays UNSCALED)
613	    //    phaseA publishes per-CTA (r,s) into opt_reduce slots (owner-computes tree,
614	    //    no float atomic, deterministic); a grid barrier; CTA0 owner-sums ascending,
615	    //    EMA-decays, updates d, broadcasts. Guarded so every other opt is byte-
616	    //    identical (no extra barrier/work). p0 (param_init) is the trajectory anchor.
617	    // DETERMINISM — FIXED-PARTITION reduction (mirrors the A/A/A-CLEAN GrokAdamW
618	    // P2.5 above + the decoder twin's P2.6), NOT the work-steal task-queue drain.
619	    // WHY THIS SHAPE (the A/A/A determinism leg): the work-steal phaseA drained the
620	    // global TaskQueue (atomicAdd(g_next_task)) in timing-dependent claim order, so
621	    // each CTA's (r,s) slot could be a different tensor subset run-to-run; with non-
622	    // associative fp32 add the partials then regroup differently and the owner's d can
623	    // differ at ULP level from step>=2 — a COMPONENT_CONTRACT deterministic-reduction
624	    // violation (not guaranteed reproducible BY CONSTRUCTION, even where empirically
625	    // bit-exact on a given GPU). A FIXED contiguous element range per CTA over the
626	    // FLAT [0,kVitTotalElems) arrays (params/param_init/grad are parallel flat blobs
627	    // → flat Σ == cross-tensor Σ) with a plain sync() is the IDENTICAL shape as the
628	    // A/A/A-CLEAN GrokAdamW P2.5 — deterministic by construction. Per-element math
629	    // still CALLS canonical prodigy_partials_step (prodigy.h, single-source).
630	    // g_next_task is UNTOUCHED (B2 reset it), so P3's drain is unchanged — no
631	    // sync_reset in P2.6.
632	    if constexpr (Opt == OptId::Prodigy) {
633	        float* r_part = opt_reduce;                  // [nCTA] per-CTA Σ d²·<g,p0−p>
634	        float* s_part = opt_reduce + nCTA;           // [nCTA] per-CTA Σ d²·|g|
635	        float* d_bc   = opt_reduce + 2 * nCTA;       // [1] reduced-d broadcast
636	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
637	        const int64_t total_p = kVitTotalElems;
638	        const int64_t pbase = total_p / nCTA, prem = total_p % nCTA;
639	        const int64_t pe0 = (int64_t)cta * pbase + (cta < prem ? cta : prem);
640	        const int64_t pecnt = pbase + (cta < prem ? 1 : 0);
641	        float r_acc = 0.0f, s_acc = 0.0f;
642	        for (int64_t i = threadIdx.x; i < pecnt; i += blockDim.x) {
643	            algo::prodigy_partials_step(params, st.param_init, grad,
644	                                        d_prev, pe0 + i, r_acc, s_acc);
645	        }
646	        float r_block, s_block;
647	        prim::block_reduce_sum2_f32(r_acc, s_acc, r_block, s_block);
648	        if (threadIdx.x == 0) { r_part[cta] = r_block; s_part[cta] = s_block; }
649	        bar.sync();   // B2.6a: all per-CTA (r,s) partials published & visible
650	        if (cta == 0 && threadIdx.x == 0) {
651	            float r_step = 0.0f, s_step = 0.0f;     // ascending-CTA owner-sum
652	            for (int c = 0; c < nCTA; ++c) { r_step += r_part[c]; s_step += s_part[c]; }
653	            const float r_ema = st.beta3 * st.prodigy_persist[0] + r_step;
654	            const float s_ema = st.beta3 * st.prodigy_persist[1] + s_step;
655	            const float d_new = algo::prodigy_update_d(d_prev, st.d_coef * r_ema, s_ema);
656	            st.prodigy_persist[0] = r_ema;          // persist UNSCALED EMA
657	            st.prodigy_persist[1] = s_ema;
658	            st.prodigy_persist[2] = d_new;          // persisted d_lr for next step
659	            d_bc[0]               = d_new;          // broadcast to all CTAs
660	        }
661	        bar.sync();   // B2.6b: d visible to every CTA before the apply
662	        st.d_factor = d_bc[0];                      // the reduced d the tail reads
663	    }
664	
665	    // ── P2.7 (Muon ONLY): grid-cooperative Newton-Schulz orthogonalization of the
666	    //    2D weights (INTEGRATION-OPTSTAGES §3). For EACH 2D matrix (kVitMuon2D) all
667	    //    CTAs cooperate: buf=μ·buf+g (buf is the PERSISTENT m-slice — momentum state,
668	    //    NOT transient), ‖buf‖_F via per-CTA partials → inv_norm, X=buf·inv_norm,
669	    //    then ns_steps × { A=XXᵀ → AX=A·X → AAX=A·AX → orth=a·X+b·AX+c·AAX, swap },
670	    //    then the canonical muon_update_step apply (decay·p + neg_lr_scale·orth). The
671	    //    1D / non-2D weights (cls_token, biases, LN γ/β) take the AdamW tail in P3.
672	    //    The elementwise bodies CALL muon.h (muon_momentum_normalize_step via the
673	    //    phaseA buf body, muon_ns_combine_step, muon_update_step); the matmuls are the
674	    //    cited new device code (the eager path delegates to torch::mm/cuBLAS). Guarded
675	    //    so every other opt is byte-identical (no extra barriers / work).
676	    if constexpr (Opt == OptId::Muon) {
677	        // Carve the per-matrix NS scratch (sized for the largest 2D weight).
678	        PrecomputeWorkspace pw{};
679	        pw.muon_X            = muon_base;
680	        pw.muon_AX           = pw.muon_X   + kVitMuonMaxNumel;
681	        pw.muon_AAX          = pw.muon_AX  + kVitMuonMaxNumel;
682	        pw.muon_orth         = pw.muon_AAX + kVitMuonMaxNumel;
683	        pw.muon_A            = pw.muon_orth + kVitMuonMaxNumel;
684	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)kVitMuonMaxRows * kVitMuonMaxRows;
685	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
686	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
687	        const int   ns_steps = 5;                 // bindings.cpp default
688	        for (int mi = 0; mi < vittc::kVitNumMuon2D; ++mi) {
689	            const vittc::VitMuon2D M = vittc::kVitMuon2D[mi];
690	            const int rows = M.rows, cols = M.cols;
691	            const int64_t numel = (int64_t)rows * cols;
692	            const int64_t off   = (int64_t)kVitOffsets[M.tidx];
693	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
694	            pw.muon_buf = st.exp_avg + off;
695	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
696	            muon_momentum_norm_phaseA(grad + off, numel, momentum, pw);
697	            bar.sync();
698	            muon_norm_reduce_phaseB(ctx, pw);
699	            bar.sync();
700	            muon_scale_X(numel, pw);
701	            bar.sync();
702	            // NS iterations. After each combine, orth holds the new iterate; swap so
703	            // the next iteration reads it as X. ns_steps swaps → final result is in
704	            // muon_X iff ns_steps even else muon_orth (we track the parity below).
705	            for (int s = 0; s < ns_steps; ++s) {
706	                // A = X Xᵀ  (M=rows,N=rows,K=cols; B transposed).
707	                muon_matmul(pw.muon_X, pw.muon_X, pw.muon_A, rows, rows, cols, cols, cols, /*bT=*/true);
708	                bar.sync();
709	                // AX = A X   (M=rows,N=cols,K=rows).
710	                muon_matmul(pw.muon_A, pw.muon_X, pw.muon_AX, rows, cols, rows, rows, cols, /*bT=*/false);
711	                bar.sync();
712	                // AAX = A (AX) (M=rows,N=cols,K=rows).
713	                muon_matmul(pw.muon_A, pw.muon_AX, pw.muon_AAX, rows, cols, rows, rows, cols, /*bT=*/false);
